artefacto.contenido:
{
  "kind": "presentation",
  "version": "1.0.0",
  "title": "Portal del asegurado: propuesta ejecutiva",
  "audience": "executive",
  "theme": "light",
  "slides": [
    {
      "id": "s1",
      "slideNumber": 1,
      "title": "Portal del asegurado",
      "layout": "titleSlide",
      "contentBlocks": [
        {
          "type": "text",
          "content": "Propuesta para el comité de dirección"
        }
      ],
      "speakerNotes": "Presentar el objetivo en una frase y pedir la decisión al final.",
      "subtitle": "Comité de dirección, octubre"
    },
    {
      "id": "s2",
      "slideNumber": 2,
      "title": "Resumen ejecutivo",
      "layout": "executiveSummary",
      "contentBlocks": [
        {
          "type": "bullets",
          "content": [
            "Treinta por ciento menos llamadas por consultas",
            "Inversión recuperada en dieciocho meses",
            "Riesgo regulatorio controlado"
          ]
        }
      ],
      "speakerNotes": "Las tres cifras salen del caso de negocio aprobado por Finanzas.",
      "keyMessage": "El portal paga su inversión en año y medio."
    },
    {
      "id": "s3",
      "slideNumber": 3,
      "title": "El problema y la propuesta",
      "layout": "problemSolution",
      "contentBlocks": [
        {
          "type": "text",
          "content": "Hoy cada consulta de cobertura es una llamada."
        },
        {
          "type": "callout",
          "content": {
            "tone": "info",
            "title": "Propuesta",
            "body": "Autoservicio con datos de cobertura y reclamaciones en línea."
          }
        }
      ],
      "speakerNotes": "Insistir en que el problema es de volumen, no de calidad de atención."
    },
    {
      "id": "s4",
      "slideNumber": 4,
      "title": "Indicadores esperados",
      "layout": "metricsKpi",
      "contentBlocks": [
        {
          "type": "kpi",
          "content": [
            {
              "label": "Llamadas por consulta",
              "value": "-30 %",
              "trend": "down",
              "detail": "Primer año"
            },
            {
              "label": "Satisfacción",
              "value": "+12 puntos",
              "trend": "up"
            },
            {
              "label": "Costo por contacto",
              "value": "Estable",
              "trend": "flat"
            }
          ]
        }
      ],
      "speakerNotes": "La satisfacción se mide con la encuesta trimestral existente."
    },
    {
      "id": "s5",
      "slideNumber": 5,
      "title": "Opciones evaluadas",
      "layout": "comparisonTable",
      "contentBlocks": [
        {
          "type": "table",
          "content": {
            "headers": [
              "Opción",
              "Costo",
              "Plazo",
              "Riesgo"
            ],
            "rows": [
              [
                "Construir sobre el portal actual",
                "Bajo",
                "6 meses",
                "Alto"
              ],
              [
                "Plataforma de mercado",
                "Medio",
                "4 meses",
                "Medio"
              ],
              [
                "Desarrollo nuevo",
                "Alto",
                "12 meses",
                "Bajo"
              ]
            ],
            "caption": "Comparación de alternativas"
          }
        }
      ],
      "speakerNotes": "La plataforma de mercado es la recomendada por equilibrio entre plazo y riesgo."
    },
    {
      "id": "s6",
      "slideNumber": 6,
      "title": "Decisión solicitada",
      "layout": "decisionSlide",
      "contentBlocks": [
        {
          "type": "callout",
          "content": {
            "tone": "warning",
            "title": "Decisión",
            "body": "Aprobar la opción de plataforma de mercado y el presupuesto de la fase 1."
          }
        },
        {
          "type": "bullets",
          "content": [
            "Presupuesto de fase 1",
            "Patrocinio de Operaciones"
          ]
        }
      ],
      "speakerNotes": "Pedir la decisión explícitamente; no cerrar sin ella.",
      "keyMessage": "Necesitamos la aprobación hoy para llegar a la campaña."
    },
    {
      "id": "s7",
      "slideNumber": 7,
      "title": "Gracias",
      "layout": "closingSlide",
      "contentBlocks": [
        {
          "type": "text",
          "content": "Preguntas y próximos pasos"
        }
      ],
      "speakerNotes": "Recordar la fecha del siguiente comité."
    }
  ]
}
